def constrained_plan(case,choice,index):
 act=choice['act'];units=Int('units');include=Bool('include');ask=Bool('ask');initiative=Bool('initiative');s=Solver();s.add(units>=0,units<=2)
 if act=='silence':s.add(units==0,include==False,ask==False,initiative==False)
